// FUNCTION: BFME2 0x00466577 size=185 name=?xfer@CaveContain@@MAEXPAVXfer@@@Z evidence=N:ledger
void CaveContain::xfer(Xfer *xfer)
{
	OpenContain::xfer(xfer);
	if (xfer->IsLightCRC())
		return;

	xfer->Version1();
	*xfer == m_needToRunOnBuildComplete;
	*xfer == m_caveIndex;

	UnsignedInt teamID = m_originalTeam ? m_originalTeam->getID() : 0;
	*xfer == teamID;
	if (xfer->IsLoading())
	{
		if (teamID != 0)
		{
			m_originalTeam = TheTeamFactory->findTeamByID(teamID);
			if (m_originalTeam == NULL)
				throw XferException(5, 0);
		}
		else
		{
			m_originalTeam = NULL;
		}
	}
}

