// FUNCTION: BFME2 0x004666C9 size=91 name=?removeFromContain@CaveContain@@UAEXPAVObject@@_N@Z evidence=N:ledger
void CaveContain::removeFromContain(Object *obj, Bool exposeStealthUnits)
{
	if (obj == NULL)
		return;

	TunnelTracker *tracker = TheCaveSystem->getTunnelTrackerForCaveIndex(m_caveIndex);
	if (!tracker->isInContainer(obj))
		return;

	tracker->removeFromContain(obj, exposeStealthUnits);

	if (getObject()->getContain())
		getObject()->getContain()->onRemoving(obj);

	obj->onRemovedFrom(getObject());
}

// FUNCTION: BFME2 0x00466724 size=92 name=?onDie@CaveContain@@UAEXPBVDamageInfo@@@Z evidence=N:ledger
void CaveContain::onDie(const DamageInfo *damageInfo)
{
	if (!getCaveContainModuleData()->m_dieMuxData.isDieApplicable(getObject(), damageInfo))
		return;
	if (getObject()->testStatus(OBJECT_STATUS_UNDER_CONSTRUCTION))
		return;
	TunnelTracker *tracker = TheCaveSystem->getTunnelTrackerForCaveIndex(m_caveIndex);
	TheCaveSystem->unregisterCave(m_caveIndex);
	tracker->onTunnelDestroyed(getObject());
}

// FUNCTION: BFME2 0x00466780 size=16 name=?onCreate@CaveContain@@UAEXXZ evidence=N:ledger
void CaveContain::onCreate()
{
	m_caveIndex = getCaveContainModuleData()->m_caveIndex;
}

// FUNCTION: BFME2 0x00466790 size=65 name=?onBuildComplete@CaveContain@@UAEXXZ evidence=N:ledger
void CaveContain::onBuildComplete()
{
	if (!shouldDoOnBuildComplete())
		return;
	m_needToRunOnBuildComplete = false;
	TheCaveSystem->registerNewCave(m_caveIndex);
	TunnelTracker *tracker = TheCaveSystem->getTunnelTrackerForCaveIndex(m_caveIndex);
	tracker->onTunnelCreated(getObject());
}

// FUNCTION: BFME2 0x004667D1 size=119 name=?tryToSetCaveIndex@CaveContain@@UAEXH@Z evidence=N:ledger
void CaveContain::tryToSetCaveIndex(Int newIndex)
{
	if (!TheCaveSystem->canSwitchIndexToIndex(m_caveIndex, newIndex))
		return;
	TunnelTracker *oldTracker = TheCaveSystem->getTunnelTrackerForCaveIndex(m_caveIndex);
	TheCaveSystem->unregisterCave(m_caveIndex);
	oldTracker->onTunnelDestroyed(getObject());
	m_caveIndex = newIndex;
	TheCaveSystem->registerNewCave(m_caveIndex);
	TunnelTracker *newTracker = TheCaveSystem->getTunnelTrackerForCaveIndex(m_caveIndex);
	newTracker->onTunnelCreated(getObject());
}

