// FUNCTION: BFME2 0x004668DC size=155 name=?onRemoving@CaveContain@@UAEXPAVObject@@@Z evidence=N:ledger
void CaveContain::onRemoving(Object *obj)
{
	OpenContain::onRemoving(obj);

	// The object leaves the cave: no longer held, back in the world managers,
	// at the cave's position and visible again.
	obj->clearDisabled(DISABLED_HELD);
	obj->rva0028DCC4();
	obj->setPosition(getObject()->getPosition());
	if (obj->getDrawable())
		obj->getDrawable()->setDrawableHidden(false);

	doUnloadSound();

	if (getCount(false) == 0)
	{
		if (obj->getTeam() != NULL)
		{
			rva00466848(m_originalTeam, false);
			m_originalTeam = NULL;
		}
		obj->clearModelConditionState(MODELCONDITION_GARRISONED);
	}
}

// FUNCTION: BFME2 0x00466977 size=217 name=?recalcApparentControllingPlayer@CaveContain@@UAEXXZ evidence=N:ledger
void CaveContain::recalcApparentControllingPlayer()
{
	if (m_originalTeam == NULL)
		m_originalTeam = getObject()->getTeam();

	if (getObject()->getTeam() == NULL)
		m_originalTeam = NULL;

	if (getCount(false) == 1)
	{
		Object *rider = *getList().objects().begin();
		if (rider->getControllingPlayer())
			rva00466848(rider->getControllingPlayer()->getDefaultTeam(), true);
	}
	else if (getCount(false) == 0)
	{
		rva00466848(m_originalTeam, false);
	}

	const Player *controller = getApparentControllingPlayer(ThePlayerList->getLocalPlayer());
	if (controller)
	{
		if (TheWritableGlobalData->m_timeOfDay == TIME_OF_DAY_NIGHT)
			getObject()->getDrawable()->setIndicatorColor(controller->getPlayerNightColor());
		else
			getObject()->getDrawable()->setIndicatorColor(controller->getPlayerColor());
	}
}

// FUNCTION: BFME2 0x00466A50 size=121 name=?removeAllContained@CaveContain@@UAEX_N@Z evidence=N:ledger
void CaveContain::removeAllContained(Bool exposeStealthUnits)
{
	TunnelTracker *myTracker = TheCaveSystem->getTunnelTrackerForCaveIndex(m_caveIndex);
	{
		ContainedItemsList fullList = myTracker->getContainedItemsList().toList();
		ContainedItemsList::const_iterator it = fullList.begin();
		while (it != fullList.end())
		{
			Object *obj = *it;
			it++;
			removeFromContain(obj, exposeStealthUnits);
		}
	}
}

